import{_ as i,C as s,c as r,o as d,j as e,a as n,a6 as t,G as c}from"./chunks/framework.BY05barL.js";const y=JSON.parse('{"title":"Administración de Memoria","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"repaso/administracion-memoria.md","filePath":"repaso/administracion-memoria.md"}'),l={name:"repaso/administracion-memoria.md"};function m(p,a,u,h,b,_){const o=s("BitmapListDemo");return d(),r("div",null,[a[1]||(a[1]=e("h1",{id:"administracion-de-memoria",tabindex:"-1"},[n("Administración de Memoria "),e("a",{class:"header-anchor",href:"#administracion-de-memoria","aria-label":'Permalink to "Administración de Memoria"'},"​")],-1)),e("details",null,[a[0]||(a[0]=t('<summary>Formas de administrar la memoria libre y ocupada</summary><h2 id="mapa-de-bits" tabindex="-1">Mapa de Bits <a class="header-anchor" href="#mapa-de-bits" aria-label="Permalink to &quot;Mapa de Bits&quot;">​</a></h2><ul><li><em>Velocidad</em>: buscar un hueco libre puede ser lento. Para cargar un proceso de <code>k</code> unidades, hay que recorrer el mapa buscando <code>k</code> bits seguidos en <code>0</code> (libres).</li><li><em>Espacio</em>: depende del tamaño de la <strong>unidad de asignación</strong>. Si es muy chica, el mapa tiene muchos bits. <ul><li>Agrandar la unidad achica el mapa, pero desperdicia memoria en la última unidad de cada proceso (fragmentación interna).</li><li>Una vez elegida la unidad, el mapa <strong>siempre ocupa lo mismo</strong>: 1 bit por unidad. No depende de la cantidad de procesos.</li></ul></li></ul><h2 id="listas-enlazadas" tabindex="-1">Listas Enlazadas <a class="header-anchor" href="#listas-enlazadas" aria-label="Permalink to &quot;Listas Enlazadas&quot;">​</a></h2><ul><li><em>Velocidad</em>: con optimizaciones es más rápida. Por ejemplo, listas separadas de procesos y huecos, o la lista de huecos ordenada por tamaño.</li><li><em>Espacio</em>: tiene un nodo por proceso y por hueco. Con pocos procesos ocupa menos que el mapa de bits; <strong>crece con la cantidad de procesos</strong>. <ul><li>Las optimizaciones (índices, dos listas) gastan más espacio a cambio de asignar y liberar más rápido.</li></ul></li></ul><h2 id="relacion-entre-huecos-y-procesos" tabindex="-1">Relación entre huecos y procesos <a class="header-anchor" href="#relacion-entre-huecos-y-procesos" aria-label="Permalink to &quot;Relación entre huecos y procesos&quot;">​</a></h2><p>Al liberar memoria, los huecos vecinos se unen: nunca hay dos huecos seguidos. Por eso hay <strong>como máximo un hueco más que procesos</strong>. En la práctica hay alrededor de la mitad de huecos que de procesos (regla del 50%, citada por Tanenbaum).</p>',7)),c(o)])])}const f=i(l,[["render",m]]);export{y as __pageData,f as default};
